def main():
    repo = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
    out_dir = os.path.join(repo, "dist", "Interface", "Translations")
    os.makedirs(out_dir, exist_ok=True)
    for k, row in T.items():
        assert len(row) == 11, (k, len(row))
        for v in row:
            assert "\t" not in v and "\n" not in v, k
    for i, lang in enumerate(LANGS):
        lines = ["$%s\t%s" % (k, row[i]) for k, row in T.items()]
        data = ("\r\n".join(lines) + "\r\n").encode("utf-16-le")
        with open(os.path.join(out_dir, "DeepSnow_%s.txt" % lang), "wb") as f:
            f.write(b"\xff\xfe" + data)
    print("wrote %d languages x %d keys to %s" % (len(LANGS), len(T), out_dir))


if __name__ == "__main__":
    main()
